#!/usr/bin/env bash
# Arena Studio -> Android APK through the GenAPK flow (generated by arena_exe_builder). Run on Linux, macOS, or inside WSL.
set -euo pipefail
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
NAME="Arena_Studio_BuildV1"
if [[ "$HERE" == /mnt/* ]]; then
  # The Windows drive is slow and breaks Android tooling: build in the Linux filesystem, copy the APK back.
  WORK="$HOME/.arena_apk_build/$NAME"
  mkdir -p "$WORK"
  if command -v rsync >/dev/null 2>&1; then
    rsync -a --delete --exclude '.buildozer' --exclude 'bin' "$HERE"/ "$WORK"/
  else
    find "$WORK" -mindepth 1 -maxdepth 1 ! -name .buildozer ! -name bin -exec rm -rf {} +
    (cd "$HERE" && tar --exclude=./.buildozer --exclude=./bin -cf - .) | (cd "$WORK" && tar -xf -)
  fi
else
  WORK="$HERE"
fi
export PATH="$HOME/.arena_venv/bin:$HOME/.local/bin:$PATH"
# Newer Ubuntu (PEP 668) blocks the "pip install --user" that Buildozer runs for its helper packages; this only affects your user folder.
export PIP_BREAK_SYSTEM_PACKAGES=1
# Android builds need a full JDK 17; a stale JAVA_HOME (JRE only, or another version) makes Buildozer say "javac not found".
JDK17="$(ls -d /usr/lib/jvm/java-17-openjdk-* 2>/dev/null | head -n 1 || true)"
if [ -n "$JDK17" ] && [ -x "$JDK17/bin/javac" ]; then export JAVA_HOME="$JDK17"; fi
if ! command -v buildozer >/dev/null 2>&1; then
  echo "buildozer was not found. Run the compiler's Install Android Tools button (or see README_ANDROID.txt)."
  exit 3
fi
cd "$WORK"
python3 genapk_arena.py
mkdir -p "$HERE/bin"
if [[ "$WORK" != "$HERE" ]]; then cp -f "$WORK"/bin/*.apk "$HERE/bin/"; fi
echo "APK ready in: $HERE/bin"
